import{_ as e,o as n,c as a,ak as r}from"./chunks/framework.B8jO0odJ.js";const y=JSON.parse('{"title":"Web3 Young Learners Encyclopedia - Complete A-Z Contents","description":"PDF page counts every page in the file, beginning with the cover as PDF page 1.","frontmatter":{"title":"Web3 Young Learners Encyclopedia - Complete A-Z Contents","description":"PDF page counts every page in the file, beginning with the cover as PDF page 1.","source":"docs/archive/source-material/Web3-Young-Learners-Encyclopedia-A-Z-Contents.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.md","filePath":"content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.md"}'),s={name:"content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.md"};function i(o,t,d,l,c,g){return n(),a("div",null,[...t[0]||(t[0]=[r('<div><h1 id="web3-young-learners-encyclopedia---complete-a-z-contents">Web3 Young Learners Encyclopedia - Complete A-Z Contents<a class="header-anchor" href="#web3-young-learners-encyclopedia---complete-a-z-contents" aria-label="Link to this section">​</a></h1><h2 id="reading-note">Reading note<a class="header-anchor" href="#reading-note" aria-label="Link to this section">​</a></h2><ul><li><strong>PDF page</strong> counts every page in the file, beginning with the cover as PDF page 1.</li><li><strong>Original section no.</strong> preserves the book&#39;s printed A-Z numbering (<code>01</code> through <code>26</code>). These are section numbers, <strong>not PDF page numbers</strong>.</li><li><strong>Printed locator</strong> is the letter/number label shown on each chapter page (for example, <code>A/01</code>).</li><li>Titles below follow the chapter-opening pages, which are more complete than the abbreviated titles in the original table of contents.</li></ul><h2 id="front-matter">Front matter<a class="header-anchor" href="#front-matter" aria-label="Link to this section">​</a></h2><table><thead><tr><th style="text-align:right;">PDF page</th><th>Section</th><th>Concise details</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><strong>Cover - Web3 Young Learners Encyclopedia</strong></td><td>Title cover for the illustrated introductory encyclopedia.</td></tr><tr><td style="text-align:right;">2</td><td><strong>Opening Remarks</strong></td><td>Welcomes readers to an A-Z journey through cryptocurrency, blockchain, and Web3; emphasizes understanding, responsible digital citizenship, and that the book does not teach trading or investing.</td></tr><tr><td style="text-align:right;">3</td><td><strong>Table of Contents</strong></td><td>Lists the A-Z chapters with identifiers <code>01</code>-<code>26</code>, but not their actual PDF page numbers; it mentions only two pieces of front matter and omits all back matter.</td></tr><tr><td style="text-align:right;">4</td><td><strong>A Message from Arshelene Lingao - Founder of Cryptita Plays</strong></td><td>Encourages young readers to approach crypto and blockchain with curiosity, creativity, confidence, and a sense that they have a place in the digital future.</td></tr><tr><td style="text-align:right;">5</td><td><strong>Gracy Chen&#39;s Message - CEO of Bitget</strong></td><td>Frames education as a bridge into Web3 and highlights the collaboration among Bitget, Blockchain4Youth, Blockchain4Her, and Cryptita Plays, particularly for underserved learners.</td></tr><tr><td style="text-align:right;">6</td><td><strong>Shaping the Future: Blockchain4Youth and Blockchain4Her</strong></td><td>Describes Bitget initiatives supporting blockchain education for young people and expanding women&#39;s participation and leadership in blockchain.</td></tr><tr><td style="text-align:right;">7</td><td><strong>How to Use This Encyclopedia</strong></td><td>Explains the alphabetical format, introduces Bunz as the guide, and recommends learning through stories and examples, moving at one&#39;s own pace, asking questions, and staying safe.</td></tr></tbody></table><h2 id="a-z-chapters">A-Z chapters<a class="header-anchor" href="#a-z-chapters" aria-label="Link to this section">​</a></h2><table><thead><tr><th style="text-align:center;">Letter</th><th style="text-align:center;">Original section no.</th><th style="text-align:center;">Printed locator</th><th style="text-align:right;">PDF page</th><th>Precise full chapter title</th><th>Useful concise chapter details</th></tr></thead><tbody><tr><td style="text-align:center;">A</td><td style="text-align:center;">01</td><td style="text-align:center;"><code>A/01</code></td><td style="text-align:right;">8</td><td><strong>Altcoins</strong></td><td>Defines altcoins as digital coins other than Bitcoin, created for varied purposes such as faster payments or private transactions. Gives Ethereum, Litecoin, and Solana as examples and notes Namecoin as the first altcoin.</td></tr><tr><td style="text-align:center;">B</td><td style="text-align:center;">02</td><td style="text-align:center;"><code>B/02</code></td><td style="text-align:right;">9</td><td><strong>Blockchain</strong></td><td>Compares a blockchain to a shared digital notebook whose recorded data cannot be erased or changed. Notes Bitcoin as its first real-world use and mentions crypto, games, and voting systems as applications.</td></tr><tr><td style="text-align:center;">C</td><td style="text-align:center;">03</td><td style="text-align:center;"><code>C/03</code></td><td style="text-align:right;">10</td><td><strong>Cryptocurrency</strong></td><td>Introduces cryptocurrency as internet-based money secured by cryptography, without a physical form or government issuer. Uses Bitcoin as the best-known example.</td></tr><tr><td style="text-align:center;">D</td><td style="text-align:center;">04</td><td style="text-align:center;"><code>D/04</code></td><td style="text-align:right;">11</td><td><strong>Decentralization</strong></td><td>Explains that control and decision-making are distributed across many people and computers rather than held by one person or company, making systems more resilient and potentially fairer.</td></tr><tr><td style="text-align:center;">E</td><td style="text-align:center;">05</td><td style="text-align:center;"><code>E/05</code></td><td style="text-align:right;">12</td><td><strong>Exchanges (Know What, Not How)</strong></td><td>Describes exchanges as websites or apps where digital assets are traded. Stresses awareness rather than participation for teens and mentions educational content and testnets.</td></tr><tr><td style="text-align:center;">F</td><td style="text-align:center;">06</td><td style="text-align:center;"><code>F/06</code></td><td style="text-align:right;">13</td><td><strong>Fiat Currency</strong></td><td>Defines fiat as government-issued money in physical or digital form and contrasts it with cryptocurrency. Everyday cash and money in payment apps are examples.</td></tr><tr><td style="text-align:center;">G</td><td style="text-align:center;">07</td><td style="text-align:center;"><code>G/07</code></td><td style="text-align:right;">14</td><td><strong>Gas Fees</strong></td><td>Explains gas fees as payments for using blockchain features, similar to road tolls, with fees rising when network traffic is high. Uses Ethereum transactions as the example.</td></tr><tr><td style="text-align:center;">H</td><td style="text-align:center;">08</td><td style="text-align:center;"><code>H/08</code></td><td style="text-align:right;">15</td><td><strong>HODL</strong></td><td>Explains the typo-derived slang for holding crypto long-term while warning that slang is not a strategy. Traces the term to a 2013 Bitcoin forum post.</td></tr><tr><td style="text-align:center;">I</td><td style="text-align:center;">09</td><td style="text-align:center;"><code>I/09</code></td><td style="text-align:right;">16</td><td><strong>Identity and Online Safety</strong></td><td>Covers personal data protection in Web3 and warns against sharing real names, passwords, private keys, or other private information with strangers. Suggests using a nickname in public spaces.</td></tr><tr><td style="text-align:center;">J</td><td style="text-align:center;">10</td><td style="text-align:center;"><code>J/10</code></td><td style="text-align:right;">17</td><td><strong>Jupiter (JUP)</strong></td><td>Introduces Jupiter as a Solana tool that searches for favorable token-swap prices. The chapter is informational and says readers do not need to use it.</td></tr><tr><td style="text-align:center;">K</td><td style="text-align:center;">11</td><td style="text-align:center;"><code>K/11</code></td><td style="text-align:right;">18</td><td><strong>Keys (Public &amp; Private)</strong></td><td>Distinguishes the shareable public key used to receive assets from the secret private key used to control them. Compares them to an email address and its password.</td></tr><tr><td style="text-align:center;">L</td><td style="text-align:center;">12</td><td style="text-align:center;"><code>L/12</code></td><td style="text-align:right;">19</td><td><strong>Ledger</strong></td><td>Defines a ledger as a transaction record. Explains that blockchain ledgers are public, resistant to change, and maintained by computers around the world.</td></tr><tr><td style="text-align:center;">M</td><td style="text-align:center;">13</td><td style="text-align:center;"><code>M/13</code></td><td style="text-align:right;">20</td><td><strong>Mining &amp; Validators</strong></td><td>Contrasts miners, who solve computational puzzles, with validators, who approve transactions. Uses Bitcoin mining and modern Ethereum/Solana validation as examples.</td></tr><tr><td style="text-align:center;">N</td><td style="text-align:center;">14</td><td style="text-align:center;"><code>N/14</code></td><td style="text-align:right;">21</td><td><strong>NFTs (Non-Fungible Tokens)</strong></td><td>Describes NFTs as unique digital items whose data can prove ownership, including art, music, collectibles, and tickets, while cautioning that uniqueness does not guarantee value.</td></tr><tr><td style="text-align:center;">O</td><td style="text-align:center;">15</td><td style="text-align:center;"><code>0/15</code> as printed</td><td style="text-align:right;">22</td><td><strong>On-Chain vs Off-Chain</strong></td><td>Distinguishes actions recorded directly on a blockchain from activity handled in a private app, server, chat, or other external system. Notes that on-chain actions are public and often incur gas fees.</td></tr><tr><td style="text-align:center;">P</td><td style="text-align:center;">16</td><td style="text-align:center;"><code>P/16</code></td><td style="text-align:right;">23</td><td><strong>Proof Systems</strong></td><td>Introduces Proof of Work and Proof of Stake as ways networks decide who may add data. Contrasts energy-intensive computing with validators who lock up crypto; cites Bitcoin, Ethereum, and Solana.</td></tr><tr><td style="text-align:center;">Q</td><td style="text-align:center;">17</td><td style="text-align:center;"><code>Q/17</code></td><td style="text-align:right;">24</td><td><strong>QR Codes in Web3</strong></td><td>Explains QR codes as scannable links that may connect to websites, apps, wallets, or crypto tools. Warns readers to scan only codes from trusted sources.</td></tr><tr><td style="text-align:center;">R</td><td style="text-align:center;">18</td><td style="text-align:center;"><code>R/18</code></td><td style="text-align:right;">25</td><td><strong>Risks, Red Flags &amp; Staying Scam-Safe</strong></td><td>Identifies fake giveaways, phishing links, shady apps, urgency, and requests for private information as warning signs. Reinforces the rule that an offer sounding too good to be true probably is.</td></tr><tr><td style="text-align:center;">S</td><td style="text-align:center;">19</td><td style="text-align:center;"><code>S/19</code></td><td style="text-align:right;">26</td><td><strong>Smart Contracts</strong></td><td>Defines smart contracts as coded agreements that execute automatically without a middleman. Gives automatic reward release after task completion as an example.</td></tr><tr><td style="text-align:center;">T</td><td style="text-align:center;">20</td><td style="text-align:center;"><code>T/20</code></td><td style="text-align:right;">27</td><td><strong>Tokens (Not Toys!)</strong></td><td>Describes blockchain-based tokens used in games, for utility, as rewards, or to represent value. Warns that not every token has real-world value.</td></tr><tr><td style="text-align:center;">U</td><td style="text-align:center;">21</td><td style="text-align:center;"><code>U/21</code></td><td style="text-align:right;">28</td><td><strong>Understanding Web3 Safety</strong></td><td>Connects Web3 freedom with personal responsibility: learn first, verify links, back up wallets, ask questions, and practice without real funds where possible.</td></tr><tr><td style="text-align:center;">V</td><td style="text-align:center;">22</td><td style="text-align:center;"><code>V/22</code></td><td style="text-align:right;">29</td><td><strong>Volatility (What It Means)</strong></td><td>Explains rapid price movement and the resulting unpredictability and risk. Uses Bitcoin&#39;s historical decline and a coin whose price may change sharply by tomorrow as examples.</td></tr><tr><td style="text-align:center;">W</td><td style="text-align:center;">23</td><td style="text-align:center;"><code>W/23</code></td><td style="text-align:right;">30</td><td><strong>Wallets (Read-Only Awareness)</strong></td><td>Compares crypto wallets to digital lockers used to hold tokens and interact with Web3 apps. Emphasizes never sharing a seed phrase and notes that cold wallets work offline.</td></tr><tr><td style="text-align:center;">X</td><td style="text-align:center;">24</td><td style="text-align:center;"><code>X/24</code></td><td style="text-align:right;">31</td><td><strong>XRP</strong></td><td>Introduces XRP as a cryptocurrency associated with Ripple and fast international payments. Notes short confirmation times and urges readers to research trends independently.</td></tr><tr><td style="text-align:center;">Y</td><td style="text-align:center;">25</td><td style="text-align:center;"><code>Y/25</code></td><td style="text-align:right;">32</td><td><strong>Your Data and Privacy in Web3</strong></td><td>Explains that controlling one&#39;s own data also creates responsibility for protecting it. Notes that wallet addresses are public but not inherently named and recommends privacy settings and unique passwords.</td></tr><tr><td style="text-align:center;">Z</td><td style="text-align:center;">26</td><td style="text-align:center;"><code>Z/26</code></td><td style="text-align:right;">33</td><td><strong>Zero-Knowledge Proofs</strong></td><td>Explains how a zero-knowledge proof can verify that a claim is true without revealing the underlying information. Uses age verification without disclosing an exact age as the example.</td></tr></tbody></table><h2 id="back-matter-and-bonus-sections">Back matter and bonus sections<a class="header-anchor" href="#back-matter-and-bonus-sections" aria-label="Link to this section">​</a></h2><table><thead><tr><th style="text-align:right;">PDF page</th><th>Section</th><th>Concise details</th></tr></thead><tbody><tr><td style="text-align:right;">34</td><td><strong>Bonus Bits for Smart Minds</strong></td><td>Divider introducing the supplemental learning and safety material.</td></tr><tr><td style="text-align:right;">35</td><td><strong>Beginner-Friendly Web3 Glossary</strong></td><td>Quick-reference definitions for blockchain explorer, consensus, DApp, DAO, testnet, seed phrase, cold wallet, hot wallet, block, and node.</td></tr><tr><td style="text-align:right;">36</td><td><strong>Top Online Scams to Watch Out For</strong></td><td>Covers fake giveaways, impersonators, phishing links, malicious airdrops, and unsolicited Discord or Telegram messages; advises using official channels and thinking before clicking.</td></tr><tr><td style="text-align:right;">37</td><td><strong>Digital Citizenship &amp; Cyber Hygiene</strong></td><td>Promotes respectful behavior, privacy protection, strong unique passwords, cautious clicking, and secure wallet backups.</td></tr><tr><td style="text-align:right;">38</td><td><strong>Reminder: What This Book Is and Isn&#39;t</strong></td><td>Restates that the book is an educational and online-safety guide, not financial advice or a trading manual; urges critical thinking and help from a trusted adult.</td></tr><tr><td style="text-align:right;">39</td><td><strong>Closing Remarks</strong></td><td>Congratulates readers, summarizes the foundational learning, and encourages continued curiosity, safety, and questioning.</td></tr><tr><td style="text-align:right;">40</td><td><strong>About Cryptita Plays</strong></td><td>Describes the initiative&#39;s mission to bring foundational blockchain and cryptocurrency education to youth in remote and underserved areas.</td></tr><tr><td style="text-align:right;">41</td><td><strong>Acknowledgments</strong></td><td>Credits Cryptita Plays and Blockchain4Youth through Bitget, along with the educators, creators, and young readers who made the educational project possible.</td></tr><tr><td style="text-align:right;">42</td><td><strong>Educational-use notice (untitled)</strong></td><td>States that the non-commercial book was created by Cryptita Plays with support from Blockchain4Youth, a Bitget initiative, for educational use only.</td></tr><tr><td style="text-align:right;">43</td><td><strong>Back cover / colophon (untitled)</strong></td><td>Displays the Blockchain4Youth and Cryptita Plays branding, the line “by Cryptita Plays x Bitget&#39;s Blockchain4Youth,” and “THIS BOOK IS NOT FOR SALE.”</td></tr></tbody></table><h2 id="discrepancies-and-omissions-in-the-original-table-of-contents">Discrepancies and omissions in the original table of contents<a class="header-anchor" href="#discrepancies-and-omissions-in-the-original-table-of-contents" aria-label="Link to this section">​</a></h2><ol><li><strong>The numbers <code>01</code>-<code>26</code> are section numbers, not PDF pages.</strong> The chapters actually appear on PDF pages 8-33, so every A-Z chapter is seven PDF pages later than its section number.</li><li><strong>Front matter is incomplete.</strong> The TOC names “Opening Remarks” and “How to Use This Encyclopedia” but gives neither a locator. It omits the cover, the TOC page itself, Arshelene Lingao&#39;s message, Gracy Chen&#39;s message, and “Shaping the Future: Blockchain4Youth and Blockchain4Her.”</li><li><strong>All bonus and back matter is omitted.</strong> PDF pages 34-43 do not appear in the TOC.</li><li><strong>Several TOC titles are shortened or differ from the chapter pages:</strong><ul><li><code>E: Exchanges</code> -&gt; <strong>Exchanges (Know What, Not How)</strong></li><li><code>J: Jupiter (Jup )</code> -&gt; <strong>Jupiter (JUP)</strong>; the TOC has inconsistent capitalization and an extra space before <code>)</code>.</li><li><code>K: Keys (Public and Private)</code> -&gt; <strong>Keys (Public &amp; Private)</strong></li><li><code>M: Mining and Validators</code> -&gt; <strong>Mining &amp; Validators</strong></li><li><code>N: NFTs</code> -&gt; <strong>NFTs (Non-Fungible Tokens)</strong></li><li><code>T: Tokens</code> -&gt; <strong>Tokens (Not Toys!)</strong></li><li><code>V: Volatility</code> -&gt; <strong>Volatility (What It Means)</strong></li><li><code>W: Wallets</code> -&gt; <strong>Wallets (Read-Only Awareness)</strong></li></ul></li><li><strong>The On-Chain chapter&#39;s printed locator contains a character error.</strong> PDF page 22 shows <code>0/15</code> with the numeral zero instead of the expected letter <code>O</code>; the TOC correctly uses <code>O</code>.</li><li><strong>PDF page 29 contains overlapping duplicate text objects.</strong> The visible Volatility chapter remains readable, but text extraction produces a garbled duplicated version of part of the definition. The chapter summary above follows the clearly visible text.</li></ol><h2 id="coverage-check">Coverage check<a class="header-anchor" href="#coverage-check" aria-label="Link to this section">​</a></h2><ul><li>Front matter: PDF pages 1-7</li><li>A-Z chapters: 26 chapters, PDF pages 8-33</li><li>Bonus and back matter: PDF pages 34-43</li><li>Total covered: all 43 PDF pages</li></ul></div>',1)])])}const p=e(s,[["render",i]]);export{y as __pageData,p as default};
